(function(root){
'use strict';
const rooms=[
{id:'threshold',name:'Threshold',description:'Name the need before choosing an action.',quest:'Observe the threshold',reward:1},
{id:'memory',name:'Memory room',description:'Read the returning lore and preserve a useful trace.',quest:'Record a memory',reward:1},
{id:'workroom',name:'Makkakah workroom',description:'Sustain the shared dwelling through a bounded act of care.',quest:'Practice care',reward:2},
{id:'turning',name:'Aantonymmakkakah turning room',description:'Reframe a grievance and consider another route toward repair.',quest:'Practice repair',reward:2},
{id:'writing',name:'Writing studio',description:'Make a story that names an issue and proposes a remedy.',quest:'Complete a writing exercise',reward:2},
{id:'machine',name:'Kerot machine room',description:'Review the difference between a proposed system and a working tool.',quest:'Check a specification',reward:1},
{id:'gathering',name:'Ashram gathering room',description:'Choose a cooperative task with clear boundaries.',quest:'Review shared stewardship',reward:2},
{id:'garden',name:'Provisioning garden',description:'Resources return through observation and measured care.',quest:'Gather a provision',reward:1}
];
function fresh(){return {format:'rasniki-game',version:1,room:'threshold',resources:3,care:0,repair:0,turns:0,quests:[],journal:[],mode:'explore'};}
function validate(raw){if(!raw||raw.format!=='rasniki-game'||raw.version!==1||!rooms.some(r=>r.id===raw.room)||!['explore','quiet'].includes(raw.mode))throw Error('Unsupported game save');for(const key of ['resources','care','repair','turns'])if(!Number.isSafeInteger(raw[key])||raw[key]<0||raw[key]>1000000)throw Error('Invalid game counters');if(!Array.isArray(raw.quests)||raw.quests.length>rooms.length||new Set(raw.quests).size!==raw.quests.length||!raw.quests.every(id=>rooms.some(r=>r.id===id)))throw Error('Invalid quest list');if(!Array.isArray(raw.journal)||raw.journal.length>100||!raw.journal.every(line=>typeof line==='string'&&line.length<=500))throw Error('Invalid journal');return {format:raw.format,version:1,room:raw.room,resources:raw.resources,care:raw.care,repair:raw.repair,turns:raw.turns,quests:[...raw.quests],journal:[...raw.journal],mode:raw.mode};}
function action(state,type,value){const next=validate(state);if(next.turns>=1000000)throw Error('Turn limit reached; start a new game');let message;switch(type){case 'move':{const room=rooms.find(r=>r.id===value);if(!room)throw Error('Unknown room');next.room=room.id;message='Entered '+room.name;break;}case 'quest':{const room=rooms.find(r=>r.id===next.room);if(next.quests.includes(room.id))throw Error('This room’s quest is already complete');next.quests.push(room.id);next.resources=Math.min(1000000,next.resources+room.reward);message='Completed: '+room.quest;break;}case 'care':if(next.resources<1)throw Error('Care needs one provision; complete a quest or rest');next.resources--;next.care=Math.min(1000000,next.care+1);message='Makkakah: one provision becomes care.';break;case 'repair':if(next.resources<1)throw Error('Repair needs one provision; complete a quest or rest');next.resources--;next.repair=Math.min(1000000,next.repair+1);message='Aantonymmakkakah: one provision supports reframing.';break;case 'rest':next.resources=Math.min(1000000,next.resources+1);message='Rested; gained one provision.';break;case 'mode':if(!['explore','quiet'].includes(value))throw Error('Unknown mode');next.mode=value;message='Mode: '+value;break;default:throw Error('Unknown game action');}next.turns++;next.journal.push(message);next.journal=next.journal.slice(-100);return next;}
function pack(state){return JSON.stringify(validate(state),null,2);}
function unpack(text){if(typeof text!=='string'||text.length>100000)throw Error('Save exceeds the text limit');let raw;try{raw=JSON.parse(text);}catch(e){throw Error('Invalid JSON save');}return validate(raw);}
root.RasnikiGame={rooms,fresh,validate,action,pack,unpack};
})(globalThis);
